INSERT INTO `announcements` (`id`, `title`, `slug`, `type`, `category`, `content`, `excerpt`, `image_type`, `featured_image`, `event_date`, `event_time`, `event_location`, `is_published`, `created_at`, `updated_at`) VALUES
(1, 'B.Sc. CSIT 2nd Year 4th Semester Examination Form Notice (2081 Batch)', 'bsc-csit-2nd-year-4th-semester-examination-form-notice-2081-batch-6a58596b9fb9f', 'notice', 'Academic', '<p>All regular and partial students of <strong>B.Sc. CSIT Second Year, Fourth Semester (2081 Batch)</strong> are informed to submit their <strong>examination forms</strong> within the specified deadline by completing the required formalities and paying the applicable fees.</p><p><strong>Form Submission Deadline:</strong> Shrawan 26, 2083<br><strong>Contact:</strong> Accounts Section &amp; B.Sc. CSIT Department</p>', NULL, 'upload', 'media/1784174570_whatsapp-image-2026-07-16-at-94525-am.jpeg', NULL, NULL, NULL, 1, '2026-07-16 07:54:15', '2026-07-16 07:54:15'),
(2, 'Registrations for GODAWARI INTRAHACK 1.0', 'registrations-for-godawari-intrahack-10-6a6167f276644', 'event', 'Academic', '<p>Registrations for GODAWARI INTRAHACK 1.0 are now officially open! 🎉</p><p>Have an innovative idea you\'ve been waiting to turn into reality? This is your opportunity to challenge yourself, collaborate with like-minded innovators, and transform your concept into a working solution. Whether you\'re passionate about software development, artificial intelligence, cybersecurity, web technologies, or creative problem-solving, GODAWARI INTRAHACK 1.0 is the perfect platform to showcase your skills and creativity.</p><p>Join us for an exciting 24-hour hackathon at Sushma Godawari College, where teams will compete to develop impactful projects, learn from the experience, and network with fellow tech enthusiasts. With only 15 team slots available and a total prize pool of NPR 28,000, every moment will count from brainstorming ideas to coding through the night and presenting your final solution.</p><p>&nbsp;</p><p>🗓 Registration Period: 18th – 31st July, 2026<br>⏱ Hackathon Duration: 24 Hours<br>👥 Limited to: 15 Teams<br>🏆 Prize Pool: NPR 28,000</p><p>&nbsp;</p><p>This is the first-ever GODAWARI INTRAHACK, and we\'re excited to make it a memorable milestone together. Gather your team, bring your best ideas, and get ready to innovate, collaborate, and compete.</p><p>🔗 Register now: itclub.godawari.edu.np/events</p><p>Don\'t wait until the last day team slots are limited and expected to fill quickly!</p>', NULL, 'upload', 'media/1784768355_752916942-2877263252659687-3885020622591494482-npng.jpeg', NULL, NULL, 'Godawari College Itahari', 1, '2026-07-23 04:46:38', '2026-07-23 04:48:04'),
(3, 'B.Sc.CSIT 2083 Entrance Result Published', 'bsccsit-2083-entrance-result-published-6a7937743e4e0', 'notice', 'Result', '<p>The <strong>B.Sc. CSIT Entrance Examination 2083 result has been published</strong> by Tribhuvan University, Institute of Science and Technology (IoST).</p><p>All candidates who appeared in the entrance examination are requested to <strong>check their results and proceed with the admission process according to the instructions provided by IoST</strong>. Eligible candidates should also carefully review the college priority and admission procedures within the specified timeframe.</p><p><strong>Congratulations to all successful candidates!</strong> We wish you all the very best for your academic journey in Computer Science and Information Technology.</p>', NULL, 'link', 'https://drive.google.com/file/d/1sxtfQ6EQZKLRtkr5hz2TUzsahUpMQsdV/view', NULL, NULL, NULL, 1, '2026-08-10 06:14:08', '2026-08-10 06:14:40'),
(4, 'समावेशी  कोटा सम्बन्धि जरूरी सूचना', 'samavasha-kata-samabnathha-janprra-sacana-6a793b2a5fd4d', 'notice', 'Academic', '<p>त्रि.वि. नियमानुसार <strong>(त्रि.वि. सेमेष्टर प्रणाली सञ्चालन विनियम २०७४)</strong> समावेशी अन्तर्गत जुनसुकै कोटामा आवेदन दिने विद्यार्थीले <strong>कक्षा ५ देखि १२ सम्म सरकारी वा सामुदायिक विद्यालयबाट पढेको हुनुपर्नेछ</strong>, अन्यथा आवेदन दिन पाइनेछैन।</p><p>त्रि.वि. नियमानुसार <strong>२०% समावेशी कोटा</strong> यस प्रकारले आरक्षण गरिएको छ।</p>', NULL, 'upload', 'media/1786329888_1786308056.pdf', NULL, NULL, NULL, 1, '2026-08-10 06:29:58', '2026-08-10 06:29:58'),
(5, 'B.Sc. CSIT कोटातर्फ भर्नाका लागि योग्य उम्मेदवारहरूको नामावली', 'bsc-csit-katatarafa-bharanaka-lga-yagaya-umamathavarahanprka-namaval-6a8ffea6b37bd', 'notice', 'Academic', '<p>गोदावरी कलेज, इटहरीले शैक्षिक वर्ष <strong>२०८३</strong> का लागि B.Sc. CSIT कोटातर्फ भर्नाका लागि योग्य उम्मेदवारहरूको नामावली प्रकाशित गरेको छ। योग्यता तथा प्राप्त र्‍याङ्कका आधारमा छनोट भएका विद्यार्थीहरूले तोकिएको मितिभित्र आवश्यक सक्कल कागजात तथा प्रतिलिपिहरूसहित कलेज प्रशासनमा उपस्थित भई अनिवार्य रूपमा भर्ना प्रक्रिया पूरा गर्नुपर्नेछ।</p>', NULL, 'upload', 'media/1787818496_08272026_6a8ff2000361a.jpg', NULL, NULL, NULL, 1, '2026-08-27 12:53:54', '2026-08-27 12:53:54');
