INSERT INTO `cms_pages` (`id`, `parent_id`, `created_by`, `title`, `title_ne`, `slug`, `status`, `content_blocks`, `content_blocks_ne`, `content_html`, `featured_image`, `template`, `meta_title`, `meta_title_ne`, `meta_description`, `meta_description_ne`, `meta_keywords`, `meta_keywords_ne`, `sort_order`, `published_at`, `created_at`, `updated_at`) VALUES
(6, NULL, NULL, 'Explore Godawari College', 'गोदावरी कलेज चिनौँ', 'about-godawari-college', 'published', '[{\"uid\": \"be0ab6f4-102a-424b-81dd-22e85032a96d\", \"data\": {\"gap\": \"normal\", \"badge\": \"Godawari College · Itahari\", \"image\": \"uploads/site/godawari-campus.jpg\", \"title\": \"A focused place to learn, grow, and build your future\", \"width\": \"wide\", \"columns\": 2, \"eyebrow\": \"Godawari College · Itahari\", \"palette\": \"image\", \"pattern\": \"grid\", \"section\": \"hero\", \"description\": \"Explore disciplined academics, practical learning, supportive faculty, and two career-focused bachelor programs affiliated with Tribhuvan University.\", \"primary_url\": \"#programs\", \"primary_label\": \"Explore Our Programs\", \"secondary_url\": \"/admissions\", \"secondary_label\": \"Admission Inquiry\", \"background_image\": \"uploads/site/godawari-campus.jpg\"}, \"type\": \"row\", \"columns\": [{\"uid\": \"998614d4-c89a-4d2e-93eb-dbb1080de325\", \"blocks\": [{\"uid\": \"cbd75bef-5be6-47a6-b321-604d93b48c46\", \"data\": {\"icon\": \"🎓\", \"text\": \"Building confidence, skills, and responsibility alongside knowledge.\", \"align\": \"left\", \"title\": \"Our Purpose\"}, \"type\": \"feature_card\"}]}, {\"uid\": \"238cfafe-dd61-41f8-a7ca-5cf0df2d3845\", \"blocks\": []}]}, {\"uid\": \"602ba849-abe1-4da3-8668-70726f9bf5a5\", \"data\": {\"gap\": \"normal\", \"width\": \"wide\", \"columns\": 4, \"palette\": \"default\", \"pattern\": \"none\", \"section\": \"stats\", \"background_image\": \"\"}, \"type\": \"row\", \"columns\": [{\"uid\": \"2402104d-e94c-4525-9e47-1ce05d2c3a96\", \"blocks\": [{\"uid\": \"d1847082-1f16-481e-bf17-e6dda1869c0c\", \"data\": {\"align\": \"center\", \"label\": \"Established\", \"value\": \"1992 AD\"}, \"type\": \"stat\"}]}, {\"uid\": \"210c6ae3-ae02-40c1-abd4-8b77c45602a1\", \"blocks\": [{\"uid\": \"5d9f6d14-2bee-44e4-a606-ec8b038b7ef2\", \"data\": {\"align\": \"center\", \"label\": \"Affiliation\", \"value\": \"Tribhuvan University\"}, \"type\": \"stat\"}]}, {\"uid\": \"09172835-bc39-4785-a96c-7852585001a8\", \"blocks\": [{\"uid\": \"f1ccf5e4-f29d-4b2f-a337-89618a1d64ac\", \"data\": {\"align\": \"center\", \"label\": \"Bachelor Programs\", \"value\": \"2\"}, \"type\": \"stat\"}]}, {\"uid\": \"cd854067-77a0-45df-95d9-c147c103c6af\", \"blocks\": [{\"uid\": \"f920ed15-a803-4095-ab69-839132d3267c\", \"data\": {\"align\": \"center\", \"label\": \"B.Sc. CSIT\", \"value\": \"36 Seats\"}, \"type\": \"stat\"}]}]}, {\"uid\": \"5fa35117-b725-4567-9407-b8913c8b2a60\", \"data\": {\"gap\": \"large\", \"width\": \"wide\", \"columns\": 2, \"palette\": \"default\", \"pattern\": \"none\", \"section\": \"normal\", \"background_image\": \"\"}, \"type\": \"row\", \"columns\": [{\"uid\": \"8294c5d8-7492-4373-83b9-257832de5542\", \"blocks\": [{\"uid\": \"f972e648-09b7-4741-8f83-3879e8fe1690\", \"data\": {\"alt\": \"An established college with a clear academic purpose\", \"url\": \"/uploads/site/godawari-csit.jpg\", \"align\": \"left\"}, \"type\": \"image\"}]}, {\"uid\": \"2580f5d3-eec0-444a-9952-5b61e35fe290\", \"blocks\": [{\"uid\": \"b40ebd11-4cd5-475f-a09f-b92f6c1d28cd\", \"data\": {\"text\": \"An established college with a clear academic purpose\", \"align\": \"left\", \"level\": \"2\"}, \"type\": \"heading\"}, {\"uid\": \"f70032e5-c54b-40e0-82ec-52e1f95768da\", \"data\": {\"text\": \"Godawari College was established in 1992 AD (2049 BS) in Itahari, Sunsari. The college offers undergraduate education for students who want strong academic foundations and practical preparation for professional life.\\n\\nOur approach is simple: teach with clarity, connect theory with practice, and support students consistently.\", \"align\": \"left\"}, \"type\": \"paragraph\"}, {\"uid\": \"17ddc17f-0607-4a61-9627-070f66a66d76\", \"data\": {\"url\": \"/admissions\", \"align\": \"left\", \"label\": \"View Admission Details\", \"style\": \"primary\"}, \"type\": \"button\"}]}]}, {\"uid\": \"23c5c3f0-2710-4d9f-8a8a-4466ccbf35cf\", \"data\": {\"gap\": \"normal\", \"title\": \"Learning that goes beyond the classroom\", \"width\": \"wide\", \"columns\": 3, \"eyebrow\": \"College Experience\", \"palette\": \"light\", \"pattern\": \"dots\", \"section\": \"cards\", \"description\": \"Learning through lectures, discussion, laboratory work, projects, presentations, and guidance from experienced faculty.\", \"background_image\": \"\"}, \"type\": \"row\", \"columns\": [{\"uid\": \"dfccc5dc-0112-4b80-9600-c193d9636a98\", \"blocks\": [{\"uid\": \"833e368e-3fd3-47c2-ac74-429cebee8e11\", \"data\": {\"icon\": \"🧪\", \"text\": \"Projects, laboratory work, and real-world examples help students apply academic concepts.\", \"align\": \"left\", \"title\": \"Practical Learning\"}, \"type\": \"feature_card\"}]}, {\"uid\": \"92328beb-9a1c-426f-8d24-6cb68fd0b452\", \"blocks\": [{\"uid\": \"add2914f-7c2c-4f3d-9f71-e06ce89fb057\", \"data\": {\"icon\": \"🎓\", \"text\": \"Clear instruction, feedback, mentorship, and academic support throughout the program.\", \"align\": \"left\", \"title\": \"Supportive Faculty\"}, \"type\": \"feature_card\"}]}, {\"uid\": \"0b4864bf-2034-425b-955f-b1137a6a0789\", \"blocks\": [{\"uid\": \"bf560b6a-cc81-443b-b4d9-4119a9cedb10\", \"data\": {\"icon\": \"🚀\", \"text\": \"Communication, teamwork, leadership, responsibility, and career awareness.\", \"align\": \"left\", \"title\": \"Professional Growth\"}, \"type\": \"feature_card\"}]}]}, {\"uid\": \"6042d5dd-7e9d-4680-816f-89935c641d23\", \"data\": {\"gap\": \"normal\", \"title\": \"Two focused paths for your bachelor journey\", \"width\": \"wide\", \"columns\": 2, \"eyebrow\": \"Our Programs\", \"palette\": \"default\", \"pattern\": \"none\", \"section\": \"cards\", \"description\": \"Both programs are affiliated with Tribhuvan University.\", \"background_image\": \"\"}, \"type\": \"row\", \"columns\": [{\"uid\": \"811e7e5a-7d70-4aa6-a72b-2288bb85dc5b\", \"blocks\": [{\"uid\": \"7227233a-7d02-4e12-9656-49ce444e3790\", \"data\": {\"alt\": \"B.Sc. CSIT\", \"url\": \"/uploads/site/godawari-csit.jpg\", \"align\": \"left\"}, \"type\": \"image\"}, {\"uid\": \"c29cee15-5593-42b4-8d00-af6802c54ba6\", \"data\": {\"text\": \"BSc Computer Science and Information Technology\", \"align\": \"left\", \"level\": \"2\"}, \"type\": \"heading\"}, {\"uid\": \"a7aa3f45-df11-4303-85b3-5fd91b9788a2\", \"data\": {\"text\": \"A four-year, eight-semester, 126-credit program combining computer science theory with information technology practice. It covers programming, systems, networks, databases, software engineering, projects, and internship.\", \"align\": \"left\"}, \"type\": \"paragraph\"}, {\"uid\": \"eb7bde5d-3af2-4c65-b93c-9ed6b04958b5\", \"data\": {\"icon\": \"💻\", \"text\": \"Tribhuvan University · 8 Semesters · 126 Credits\", \"align\": \"left\", \"title\": \"36 Seats · 4 Years\"}, \"type\": \"feature_card\"}, {\"uid\": \"e98ea48b-7c38-4892-84d3-57882849dab4\", \"data\": {\"url\": \"/pages/bsc-csit\", \"align\": \"left\", \"label\": \"Explore Full Program\", \"style\": \"primary\"}, \"type\": \"button\"}]}, {\"uid\": \"7822e736-1b05-47e7-9f2d-2063c02cc47c\", \"blocks\": [{\"uid\": \"3e555736-4221-45d7-bcc6-34a468cd419a\", \"data\": {\"alt\": \"BBS\", \"url\": \"/uploads/site/godawari-bbs.jpg\", \"align\": \"left\"}, \"type\": \"image\"}, {\"uid\": \"7ab9f2b9-7cc9-43cb-9614-f5e62a55dbc8\", \"data\": {\"text\": \"Bachelor of Business Studies\", \"align\": \"left\", \"level\": \"2\"}, \"type\": \"heading\"}, {\"uid\": \"9bb871c1-0cfd-49ac-9230-2ef1f37a4b3d\", \"data\": {\"text\": \"A four-year, eight-semester, 120-credit program building management and practical business skills through accounting, finance, economics, marketing, research, and entrepreneurship.\", \"align\": \"left\"}, \"type\": \"paragraph\"}, {\"uid\": \"adc054f3-3c28-4d89-a647-ff28e19f2ea2\", \"data\": {\"icon\": \"📊\", \"text\": \"Tribhuvan University · 8 Semesters · 120 Credits\", \"align\": \"left\", \"title\": \"4 Years\"}, \"type\": \"feature_card\"}, {\"uid\": \"a0fb1019-6267-4adb-8d3d-025b32e470d6\", \"data\": {\"url\": \"/pages/bbs\", \"align\": \"left\", \"label\": \"Explore Full Program\", \"style\": \"primary\"}, \"type\": \"button\"}]}]}, {\"uid\": \"6bb11f60-3a5c-4fa9-be20-0a4e17e9ed09\", \"data\": {\"gap\": \"large\", \"width\": \"wide\", \"columns\": 2, \"palette\": \"green\", \"pattern\": \"dots\", \"section\": \"normal\", \"background_image\": \"\"}, \"type\": \"row\", \"columns\": [{\"uid\": \"ec197bd4-dae9-4162-aeff-05056fc0a401\", \"blocks\": [{\"uid\": \"4e62de38-67d6-4f2e-8c59-731f0a05e87a\", \"data\": {\"alt\": \"Message from the Campus Chief\", \"url\": \"/media/1784010094_bodh-raj-nepal.png\", \"align\": \"left\"}, \"type\": \"image\"}]}, {\"uid\": \"bbc7f0e1-6aab-4b9f-b3a8-4df5513ca007\", \"blocks\": [{\"uid\": \"fce6edd9-9513-44be-8abc-2b0aac335b03\", \"data\": {\"text\": \"Message from the Campus Chief\", \"align\": \"left\", \"level\": \"2\"}, \"type\": \"heading\"}, {\"uid\": \"476a8617-e460-4033-8244-25c57045ea6d\", \"data\": {\"text\": \"It is my great pleasure to welcome you to Godawari College, Itahari. Our institution is dedicated to providing quality higher education that empowers students with the knowledge, skills, values, and confidence needed to excel in an ever-changing global environment.\\n\\nAt Godawari College, we believe that education extends beyond the classroom. Our commitment is to foster academic excellence while identifying and nurturing each student\'s unique talents, creativity, leadership potential, and innovative thinking. Through a learner-centered environment, experienced faculty members, modern teaching methodologies, practical learning opportunities, and continuous academic support, we strive to prepare our students for both professional success and lifelong learning.\\n\\nWe place equal emphasis on character development, ethical values, discipline, teamwork, and social responsibility. Our goal is to develop graduates who are not only academically competent but also responsible citizens capable of contributing positively to society and the nation\'s sustainable development.\\n\\nWhether you choose our BSc CSIT or BBS program, you will find an environment that encourages intellectual curiosity, research, critical thinking, and personal growth. We are committed to helping every student realize their full potential and become confident professionals ready to meet the challenges of the future.\", \"align\": \"left\"}, \"type\": \"paragraph\"}]}]}, {\"uid\": \"b485782a-5189-4f29-a596-3aaeb2919183\", \"data\": {\"gap\": \"normal\", \"title\": \"Find the program that matches your future\", \"width\": \"wide\", \"columns\": 1, \"eyebrow\": \"Your Next Step\", \"palette\": \"dark\", \"pattern\": \"grid\", \"section\": \"cta\", \"description\": \"Talk with our admission team about B.Sc. CSIT, BBS, eligibility, documents, and the application process.\", \"primary_url\": \"/admissions\", \"primary_label\": \"Admission Inquiry\", \"secondary_url\": \"/contact\", \"secondary_label\": \"Contact the College\", \"background_image\": \"\"}, \"type\": \"row\", \"columns\": [{\"uid\": \"b093210e-e90e-4eef-bedf-ed24bbd48ebf\", \"blocks\": []}]}]', '[{\"uid\": \"53ee6ce6-d85b-426b-8c1e-b197ddfe7662\", \"data\": {\"gap\": \"normal\", \"badge\": \"गोदावरी कलेज · इटहरी\", \"image\": \"uploads/site/godawari-campus.jpg\", \"title\": \"सिक्न, बढ्न र भविष्य बनाउन केन्द्रित शैक्षिक थलो\", \"width\": \"wide\", \"columns\": 2, \"eyebrow\": \"गोदावरी कलेज · इटहरी\", \"palette\": \"image\", \"pattern\": \"grid\", \"section\": \"hero\", \"description\": \"अनुशासित अध्ययन, व्यवहारिक सिकाइ, सहयोगी शिक्षक र त्रिभुवन विश्वविद्यालयबाट सम्बन्धन प्राप्त दुई करियर केन्द्रित स्नातक कार्यक्रमसहितको कलेज अनुभव।\", \"primary_url\": \"#programs\", \"primary_label\": \"हाम्रा कार्यक्रम हेर्नुहोस्\", \"secondary_url\": \"/admissions\", \"secondary_label\": \"भर्ना सोधपुछ\", \"background_image\": \"uploads/site/godawari-campus.jpg\"}, \"type\": \"row\", \"columns\": [{\"uid\": \"b92b3964-b09a-402f-af66-a0f6eb49b83a\", \"blocks\": [{\"uid\": \"d09600ad-1a80-400b-9c36-7ba5311cf14e\", \"data\": {\"icon\": \"🎓\", \"text\": \"ज्ञानसँगै आत्मविश्वास, सीप र जिम्मेवारी विकास।\", \"align\": \"left\", \"title\": \"हाम्रो उद्देश्य\"}, \"type\": \"feature_card\"}]}, {\"uid\": \"cfa72742-1c62-4be7-b4bc-1ba765e8ae30\", \"blocks\": []}]}, {\"uid\": \"429c5fbb-2daf-4af9-964b-80147c88b3c5\", \"data\": {\"gap\": \"normal\", \"width\": \"wide\", \"columns\": 4, \"palette\": \"default\", \"pattern\": \"none\", \"section\": \"stats\", \"background_image\": \"\"}, \"type\": \"row\", \"columns\": [{\"uid\": \"c63ab9fd-2057-4627-8763-c34889f2c048\", \"blocks\": [{\"uid\": \"1cda0301-bdc7-477d-be48-718a87d805f7\", \"data\": {\"align\": \"center\", \"label\": \"स्थापना\", \"value\": \"१९९२ ई.\"}, \"type\": \"stat\"}]}, {\"uid\": \"694c043a-9a35-42fc-919c-f823884a75bc\", \"blocks\": [{\"uid\": \"96b1c31f-fd17-46b0-9116-e2937437aa05\", \"data\": {\"align\": \"center\", \"label\": \"सम्बन्धन\", \"value\": \"त्रिभुवन विश्वविद्यालय\"}, \"type\": \"stat\"}]}, {\"uid\": \"316e2101-1bd5-4a27-9321-c269d1c86686\", \"blocks\": [{\"uid\": \"0b58788b-84ca-4a24-ab98-0d0c226d8d89\", \"data\": {\"align\": \"center\", \"label\": \"स्नातक कार्यक्रम\", \"value\": \"२\"}, \"type\": \"stat\"}]}, {\"uid\": \"ca74a233-ea3d-465d-91de-a70fe8fec497\", \"blocks\": [{\"uid\": \"d1b903af-2b0a-4dc1-bf25-f1144cb38d45\", \"data\": {\"align\": \"center\", \"label\": \"B.Sc. CSIT\", \"value\": \"३६ सिट\"}, \"type\": \"stat\"}]}]}, {\"uid\": \"d2d28d31-eb26-45cf-a0bb-57b1267c6150\", \"data\": {\"gap\": \"large\", \"width\": \"wide\", \"columns\": 2, \"palette\": \"default\", \"pattern\": \"none\", \"section\": \"normal\", \"background_image\": \"\"}, \"type\": \"row\", \"columns\": [{\"uid\": \"9da65a6e-94f1-43e0-b618-65ab6262130c\", \"blocks\": [{\"uid\": \"8c9f09e6-0b4d-40a3-ae3e-53c80a4d2e9b\", \"data\": {\"alt\": \"स्पष्ट शैक्षिक उद्देश्य भएको स्थापित कलेज\", \"url\": \"/uploads/site/godawari-csit.jpg\", \"align\": \"left\"}, \"type\": \"image\"}]}, {\"uid\": \"88844d61-fbb9-4bda-823a-ad4f1bbc8497\", \"blocks\": [{\"uid\": \"2104cc92-54b8-433c-8c31-a66d4359a1d0\", \"data\": {\"text\": \"स्पष्ट शैक्षिक उद्देश्य भएको स्थापित कलेज\", \"align\": \"left\", \"level\": \"2\"}, \"type\": \"heading\"}, {\"uid\": \"c67a66e4-afff-4131-a2d3-5e6273d50ffd\", \"data\": {\"text\": \"गोदावरी कलेज सन् १९९२ (वि.सं. २०४९) मा इटहरी, सुनसरीमा स्थापना भएको हो। कलेजले बलियो शैक्षिक आधार र व्यावसायिक जीवनका लागि व्यवहारिक तयारी चाहने विद्यार्थीलाई स्नातक शिक्षा प्रदान गर्छ।\\n\\nहाम्रो दृष्टिकोण सरल छ: स्पष्ट अध्यापन, सिद्धान्तलाई व्यवहारसँग जोड्ने सिकाइ र निरन्तर विद्यार्थी सहयोग।\", \"align\": \"left\"}, \"type\": \"paragraph\"}, {\"uid\": \"2ad2b93c-452a-413e-a45c-357449544be2\", \"data\": {\"url\": \"/admissions\", \"align\": \"left\", \"label\": \"भर्ना विवरण हेर्नुहोस्\", \"style\": \"primary\"}, \"type\": \"button\"}]}]}, {\"uid\": \"bffa7dd1-b562-4818-bf29-8bee386d6382\", \"data\": {\"gap\": \"normal\", \"title\": \"कक्षाभन्दा बाहिरसम्म फैलिएको सिकाइ\", \"width\": \"wide\", \"columns\": 3, \"eyebrow\": \"कलेज अनुभव\", \"palette\": \"light\", \"pattern\": \"dots\", \"section\": \"cards\", \"description\": \"व्याख्यान, छलफल, प्रयोगशाला, परियोजना, प्रस्तुति र अनुभवी शिक्षकको मार्गदर्शनबाट सिकाइ।\", \"background_image\": \"\"}, \"type\": \"row\", \"columns\": [{\"uid\": \"6f120405-9368-45a0-a0f5-4545ce3a9554\", \"blocks\": [{\"uid\": \"b32d66e8-6216-4fd8-b09c-0d2e14393eca\", \"data\": {\"icon\": \"🧪\", \"text\": \"परियोजना, प्रयोगशाला र वास्तविक उदाहरणले अवधारणालाई व्यवहारमा उतार्न सहयोग गर्छ।\", \"align\": \"left\", \"title\": \"व्यवहारिक सिकाइ\"}, \"type\": \"feature_card\"}]}, {\"uid\": \"0f013165-4e51-44e6-a66f-259cd29693dd\", \"blocks\": [{\"uid\": \"843aa0d5-ff7f-494c-9759-6a7f1cbacd3a\", \"data\": {\"icon\": \"🎓\", \"text\": \"स्पष्ट अध्यापन, पृष्ठपोषण, परामर्श र शैक्षिक सहयोग।\", \"align\": \"left\", \"title\": \"सहयोगी शिक्षक\"}, \"type\": \"feature_card\"}]}, {\"uid\": \"a672496d-485c-4656-b839-6dd80b47be61\", \"blocks\": [{\"uid\": \"b5fbb2aa-912b-4bf2-ae36-cc5e4670f0dd\", \"data\": {\"icon\": \"🚀\", \"text\": \"सञ्चार, सहकार्य, नेतृत्व, जिम्मेवारी र करियर चेतना विकास।\", \"align\": \"left\", \"title\": \"व्यावसायिक विकास\"}, \"type\": \"feature_card\"}]}]}, {\"uid\": \"2833bf4b-b012-44eb-b57d-fb58f9fe1200\", \"data\": {\"gap\": \"normal\", \"title\": \"स्नातक यात्राका लागि दुई केन्द्रित बाटा\", \"width\": \"wide\", \"columns\": 2, \"eyebrow\": \"हाम्रा कार्यक्रम\", \"palette\": \"default\", \"pattern\": \"none\", \"section\": \"cards\", \"description\": \"दुवै कार्यक्रम त्रिभुवन विश्वविद्यालयबाट सम्बन्धन प्राप्त छन्।\", \"background_image\": \"\"}, \"type\": \"row\", \"columns\": [{\"uid\": \"6ca2fa4a-ffbb-44cd-a31b-a192a301828f\", \"blocks\": [{\"uid\": \"0b89442e-7291-4175-9907-7e83eb656f34\", \"data\": {\"alt\": \"B.Sc. CSIT\", \"url\": \"/uploads/site/godawari-csit.jpg\", \"align\": \"left\"}, \"type\": \"image\"}, {\"uid\": \"df714f73-c21f-4dca-b455-4967784bd169\", \"data\": {\"text\": \"BSc Computer Science and Information Technology\", \"align\": \"left\", \"level\": \"2\"}, \"type\": \"heading\"}, {\"uid\": \"417c6739-c9b7-415d-836a-e4c0315d0d8b\", \"data\": {\"text\": \"कम्प्युटर विज्ञानको सिद्धान्त र सूचना प्रविधिको व्यवहारिक प्रयोग जोड्ने चार वर्षे, आठ सेमेस्टरको १२६ क्रेडिट कार्यक्रम। प्रोग्रामिङ, प्रणाली, नेटवर्क, डेटाबेस, सफ्टवेयर इन्जिनियरिङ, परियोजना र इन्टर्नसिप समेटिन्छ।\", \"align\": \"left\"}, \"type\": \"paragraph\"}, {\"uid\": \"2f3e18f1-2665-4584-b521-8c465f64daac\", \"data\": {\"icon\": \"💻\", \"text\": \"Tribhuvan University · 8 Semesters · 126 Credits\", \"align\": \"left\", \"title\": \"36 Seats · 4 Years\"}, \"type\": \"feature_card\"}, {\"uid\": \"b3cc16c3-958f-4af1-9cc4-c990559287ad\", \"data\": {\"url\": \"/pages/bsc-csit\", \"align\": \"left\", \"label\": \"विस्तृत कार्यक्रम हेर्नुहोस्\", \"style\": \"primary\"}, \"type\": \"button\"}]}, {\"uid\": \"21f63f57-17f3-4a49-84e5-a6368e8654a0\", \"blocks\": [{\"uid\": \"9606787e-d46a-4f3e-b88c-481c6b3fc0a7\", \"data\": {\"alt\": \"BBS\", \"url\": \"/uploads/site/godawari-bbs.jpg\", \"align\": \"left\"}, \"type\": \"image\"}, {\"uid\": \"5c1ca63a-6f9b-47de-ac74-22e69303cbd2\", \"data\": {\"text\": \"Bachelor of Business Studies\", \"align\": \"left\", \"level\": \"2\"}, \"type\": \"heading\"}, {\"uid\": \"c80a1424-cd39-4ed5-b4f6-1b5d4806e9bd\", \"data\": {\"text\": \"व्यवस्थापन र व्यवहारिक व्यवसाय सीप विकास गर्ने चार वर्षे, आठ सेमेस्टरको १२० क्रेडिट कार्यक्रम। लेखा, वित्त, अर्थशास्त्र, बजारीकरण, अनुसन्धान र उद्यमशीलता समेटिन्छ।\", \"align\": \"left\"}, \"type\": \"paragraph\"}, {\"uid\": \"bd320b1d-c713-4cea-ab9f-199e5471b067\", \"data\": {\"icon\": \"📊\", \"text\": \"Tribhuvan University · 8 Semesters · 120 Credits\", \"align\": \"left\", \"title\": \"4 Years\"}, \"type\": \"feature_card\"}, {\"uid\": \"0d7495d3-b960-45b5-bab7-20605672fe80\", \"data\": {\"url\": \"/pages/bbs\", \"align\": \"left\", \"label\": \"विस्तृत कार्यक्रम हेर्नुहोस्\", \"style\": \"primary\"}, \"type\": \"button\"}]}]}, {\"uid\": \"26ac774a-0bcd-438a-ba9b-05ddc28d21f3\", \"data\": {\"gap\": \"large\", \"width\": \"wide\", \"columns\": 2, \"palette\": \"green\", \"pattern\": \"dots\", \"section\": \"normal\", \"background_image\": \"\"}, \"type\": \"row\", \"columns\": [{\"uid\": \"a000fccf-0851-4390-a8cb-75c123afb002\", \"blocks\": [{\"uid\": \"fa2d6bf2-f2ae-4d3d-9fc1-8ac8c3237f7c\", \"data\": {\"alt\": \"क्याम्पस प्रमुखको सन्देश\", \"url\": \"/media/1784010094_bodh-raj-nepal.png\", \"align\": \"left\"}, \"type\": \"image\"}]}, {\"uid\": \"9bbb15ae-0659-4ec0-83cd-4d46df4854d2\", \"blocks\": [{\"uid\": \"a380258e-82b1-40a7-b933-fcfecd0bbd17\", \"data\": {\"text\": \"क्याम्पस प्रमुखको सन्देश\", \"align\": \"left\", \"level\": \"2\"}, \"type\": \"heading\"}, {\"uid\": \"b8d8deea-1743-4dcd-996e-5c74d3a2be04\", \"data\": {\"text\": \"हाम्रो कलेज आवश्यक सीप विकास, विद्यार्थी प्रतिभा पहिचान र नवीन सोच प्रवर्द्धन गर्न प्रतिबद्ध छ। हामी राष्ट्रको विकासमा योगदान दिन सक्ने गतिशील र जिम्मेवार नागरिक निर्माण गर्न चाहन्छौँ।\", \"align\": \"left\"}, \"type\": \"paragraph\"}]}]}, {\"uid\": \"14a5de19-1264-4419-9b6b-d6fc7a43f6ee\", \"data\": {\"gap\": \"normal\", \"title\": \"आफ्नो भविष्यसँग मिल्ने कार्यक्रम रोज्नुहोस्\", \"width\": \"wide\", \"columns\": 1, \"eyebrow\": \"अर्को कदम\", \"palette\": \"dark\", \"pattern\": \"grid\", \"section\": \"cta\", \"description\": \"B.Sc. CSIT, BBS, योग्यता, कागजात र आवेदन प्रक्रियाबारे हाम्रो भर्ना टोलीसँग कुरा गर्नुहोस्।\", \"primary_url\": \"/admissions\", \"primary_label\": \"भर्ना सोधपुछ\", \"secondary_url\": \"/contact\", \"secondary_label\": \"कलेजमा सम्पर्क गर्नुहोस्\", \"background_image\": \"\"}, \"type\": \"row\", \"columns\": [{\"uid\": \"9e617c5e-cf5a-47c7-b080-193169cc1b28\", \"blocks\": []}]}]', NULL, 'uploads/site/godawari-campus.jpg', 'wide', 'Explore Godawari College | B.Sc. CSIT and BBS', 'गोदावरी कलेज चिनौँ | B.Sc. CSIT र BBS', 'Explore Godawari College in Itahari, its Tribhuvan University affiliation, student-focused learning environment, B.Sc. CSIT program with 36 seats, and BBS program.', 'इटहरीको गोदावरी कलेज, त्रिभुवन विश्वविद्यालय सम्बन्धन, विद्यार्थी केन्द्रित सिकाइ, ३६ सिटको B.Sc. CSIT र BBS कार्यक्रमबारे जान्नुहोस्।', 'Godawari College, BSc CSIT Itahari, BBS Itahari, Tribhuvan University college', 'गोदावरी कलेज, BSc CSIT इटहरी, BBS इटहरी', 1, '2026-07-14 07:09:23', '2026-07-14 07:09:23', '2026-07-14 07:39:46'),
(7, NULL, NULL, 'BSc CSIT at Godawari College, Itahari', 'BSc Computer Science and Information Technology', 'bsc-csit', 'published', '[{\"uid\":\"13cbeaf4-9650-4deb-a2b4-fade34cf311d\",\"data\":{\"gap\":\"normal\",\"badge\":\"36 Seats · 4 Years · 8 Semesters\",\"image\":\"uploads/site/godawari-csit.jpg\",\"title\":\"BSc CSIT at Godawari College, Itahari\",\"width\":\"wide\",\"columns\":2,\"eyebrow\":\"Our Program\",\"palette\":\"image\",\"pattern\":\"grid\",\"section\":\"hero\",\"description\":\"A Tribhuvan University computing degree combining computer science theory with practical information technology, projects, and internship.\",\"primary_url\":\"/admissions\",\"primary_label\":\"Admission Inquiry\",\"secondary_url\":\"/about\",\"secondary_label\":\"Explore the College\",\"background_image\":\"uploads/site/godawari-csit.jpg\"},\"type\":\"row\",\"columns\":[{\"uid\":\"a0c931a9-8868-470d-a335-2f4009566a35\",\"blocks\":[{\"uid\":\"88c4fc08-0870-4af6-ae5a-384c20b99a4c\",\"data\":{\"icon\":\"🎓\",\"text\":\"Tribhuvan University\",\"align\":\"left\",\"title\":\"126 Credits\"},\"type\":\"feature_card\"}]},{\"uid\":\"3631d093-ba63-4546-bea5-bb68c0cb78f6\",\"blocks\":[]}]},{\"uid\":\"6ca3c023-e945-45eb-b288-03e546d59c87\",\"data\":{\"gap\":\"normal\",\"width\":\"wide\",\"columns\":3,\"palette\":\"default\",\"pattern\":\"none\",\"section\":\"stats\",\"background_image\":\"\"},\"type\":\"row\",\"columns\":[{\"uid\":\"c67704b5-caaa-4913-93f7-d6b829c2c8a4\",\"blocks\":[{\"uid\":\"acd1d788-b10c-4aa9-9da1-d9aa5cd39b20\",\"data\":{\"align\":\"center\",\"label\":\"University\",\"value\":\"Tribhuvan University\"},\"type\":\"stat\"}]},{\"uid\":\"3bf089be-a593-43bc-984d-46a86a456031\",\"blocks\":[{\"uid\":\"af59d78a-6ac0-4d0d-9bac-2bbb6bd8d405\",\"data\":{\"align\":\"center\",\"label\":\"Duration\",\"value\":\"36 Seats · 4 Years · 8 Semesters\"},\"type\":\"stat\"}]},{\"uid\":\"e04b8bbf-fc09-4893-b1aa-7cdbb3afe14b\",\"blocks\":[{\"uid\":\"0b1b4ecd-2066-471c-997a-e0cc0196de80\",\"data\":{\"align\":\"center\",\"label\":\"Academic Load\",\"value\":\"126 Credits\"},\"type\":\"stat\"}]}]},{\"uid\":\"49571e15-51c5-4840-afa1-0332cf9d952a\",\"data\":{\"gap\":\"large\",\"width\":\"wide\",\"columns\":2,\"palette\":\"default\",\"pattern\":\"none\",\"section\":\"normal\",\"background_image\":\"\"},\"type\":\"row\",\"columns\":[{\"uid\":\"63a39de3-d343-4bd4-aee6-a995239cf355\",\"blocks\":[{\"uid\":\"f3bb7f97-d816-413b-a6b9-840d6255f106\",\"data\":{\"alt\":\"BSc CSIT at Godawari College, Itahari\",\"url\":\"/uploads/site/godawari-csit.jpg\",\"align\":\"left\"},\"type\":\"image\"}]},{\"uid\":\"8ac9ce52-9f33-4efe-bb32-fd31b5e6e2e4\",\"blocks\":[{\"uid\":\"8b390a24-8a0d-44e2-8a52-0880ff10863c\",\"data\":{\"text\":\"Program Overview\",\"align\":\"left\",\"level\":\"2\"},\"type\":\"heading\"},{\"uid\":\"112ee5f6-f646-489e-a172-1ebf5c3bd19a\",\"data\":{\"text\":\"The Bachelor of Computer Science and Information Technology (B.Sc.CSIT) curriculum is designed by closely following the courses offered at accredited international universities, subject to the condition that the intake students have completed 12 years of schooling in the science stream or equivalent from any university recognized by Tribhuvan University (TU). In addition to the foundation and core Computer Science and Information Technology courses, the program offers several elective courses to meet the demand for high-technology application development. The foundation and core courses are designed to meet the undergraduate academic program requirement, and the service courses are designed to meet the needs of fast-changing computer technology and applications. Students enrolled in the four-year B.Sc.CSIT program are required to take courses in the design and implementation of computer software systems, a foundation in the theoretical model of computer science, and a functional background of computer hardware. All undergraduate students are required to complete 126 credit hours of computer science courses and allied courses. Objective: The main objective of the B.Sc.CSIT program is to provide students with intensive knowledge and skills in different areas of computer science and information technology, including design, theory, programming, and application of computer systems. It is envisaged that graduates of this program will be equipped with the necessary knowledge of computer software and hardware systems.\",\"align\":\"left\"},\"type\":\"paragraph\"}]}]},{\"uid\":\"18cf6d41-0d3a-45a5-aba2-e5bc1edcd1a0\",\"data\":{\"gap\":\"normal\",\"title\":\"What you study and where it can lead\",\"width\":\"wide\",\"columns\":2,\"eyebrow\":\"Program Details\",\"palette\":\"light\",\"pattern\":\"dots\",\"section\":\"cards\",\"description\":\"Explore the core subjects, practical learning areas, and career directions covered by this four-year TU BSc CSIT program in Itahari.\",\"background_image\":\"\"},\"type\":\"row\",\"columns\":[{\"uid\":\"b3c7bdc7-1968-4590-99f4-88a47af2dd9f\",\"blocks\":[{\"uid\":\"ffe478ab-a8ee-4cd5-af28-a4a1f51c92eb\",\"data\":{\"icon\":\"📘\",\"text\":\"Core area of study\",\"align\":\"left\",\"title\":\"Programming and Data Structures\"},\"type\":\"feature_card\"},{\"uid\":\"192517d0-b6d5-4e15-882d-ae9e771eea83\",\"data\":{\"icon\":\"📘\",\"text\":\"Core area of study\",\"align\":\"left\",\"title\":\"Algorithms and Computer Systems\"},\"type\":\"feature_card\"},{\"uid\":\"b7e80f73-a179-4f4e-8152-7931cb408176\",\"data\":{\"icon\":\"📘\",\"text\":\"Core area of study\",\"align\":\"left\",\"title\":\"Database and Computer Networks\"},\"type\":\"feature_card\"},{\"uid\":\"b5f4f885-c13b-4895-86d1-14ddc9e99df0\",\"data\":{\"icon\":\"📘\",\"text\":\"Core area of study\",\"align\":\"left\",\"title\":\"Software Engineering, Projects, and Internship\"},\"type\":\"feature_card\"}]},{\"uid\":\"58fc8c52-24b6-428d-a065-03c585407e80\",\"blocks\":[{\"uid\":\"1737c40e-44e9-4954-99a1-ed826c362ec7\",\"data\":{\"icon\":\"🚀\",\"text\":\"Potential professional direction\",\"a