INSERT INTO `seo_settings` (`id`, `page_name`, `meta_title`, `meta_description`, `meta_keywords`, `created_at`, `updated_at`) VALUES
(1, 'home', 'Godawari College Home | Itahari\'s Premier Education Hub', 'Discover Godawari College in Itahari, Sunsari. Join us to foster excellence and inspire your future. Enroll today for a brighter tomorrow!', 'Godawari College, Godawari College Itahari, BSc CSIT Nepal, BSc CSIT Itahari, BBS College Nepal, TU Affiliated College, Tribhuvan University College, IT College Nepal, College in Itahari, Higher Education Nepal, education in Sunsari, quality education Itahari, community trust education, inspiring futures, academic excellence Itahari, vocational training Nepal', '2026-07-14 06:25:52', '2026-07-14 06:25:52'),
(2, 'about', 'About Godawari College | Itahari\'s Premier Educational Institution', 'Discover the mission and vision of Godawari College in Itahari. Join us in fostering excellence and inspiring futures. Learn more about us today!', 'Godawari College, Godawari College Itahari, BSc CSIT Nepal, BSc CSIT Itahari, BBS College Nepal, TU Affiliated College, Tribhuvan University College, IT College Nepal, College in Itahari, Higher Education Nepal, education in Sunsari, Itahari educational institution, trusted college in Itahari, college values, leadership in education, inspiring futures', '2026-07-14 06:26:01', '2026-07-14 06:26:01'),
(3, 'admissions', 'Admissions at Godawari College, Itahari | Enroll Now', 'Join Godawari College in Itahari for quality education. Explore admissions, class availability, and apply today to foster excellence and inspire futures.', 'Godawari College, Godawari College Itahari, admissions Itahari, school enrollment Sunsari, admission inquiry Godawari, apply BSc CSIT, BBS College admissions, class availability Itahari, TU affiliated admissions, higher education Nepal, enroll Godawari College, Itahari education, BSc CSIT application, BBS program Itahari, quality education Sunsari, Godawari College application process, college admissions Nepal, Itahari higher education, Godawari College programs', '2026-07-14 06:26:11', '2026-07-14 06:26:11'),
(4, 'notices', 'Notices - Godawari College, Itahari | Latest Updates', 'Stay updated with the latest notices at Godawari College, Itahari. Check exam routines and school events. Visit our page for more information!', 'Godawari College, Godawari College Itahari, Notices Itahari, exam routines, school events, official updates, BSc CSIT Nepal, BSc CSIT Itahari, BBS College Nepal, TU Affiliated College, Tribhuvan University College, IT College Nepal, College in Itahari, Higher Education Nepal, Sunsari education, Latamandau notices, Godawari College updates', '2026-07-14 06:26:18', '2026-07-14 06:26:18'),
(5, 'gallery', 'Godawari College Gallery | Itahari Campus Life & Events', 'Explore the vibrant life at Godawari College, Itahari through our gallery. Discover sports, academics, and cultural events. Join us today!', 'Godawari College, Godawari College Itahari, campus life, sports events, academic programs, cultural programs, BSc CSIT Nepal, BSc CSIT Itahari, BBS College Nepal, TU Affiliated College, Tribhuvan University College, IT College Nepal, College in Itahari, Higher Education Nepal, Sunsari education, Latamandau college, Godawari College gallery, student life Itahari', '2026-07-14 06:26:26', '2026-07-14 06:26:26'),
(6, 'faculty', 'Faculty at Godawari College, Itahari - Expert Teachers', 'Discover the highly qualified faculty at Godawari College, Itahari. Join us to foster excellence and inspire your future today!', 'Godawari College, Faculty at Godawari College, Itahari faculty, expert teachers Itahari, qualified faculty Sunsari, BSc CSIT faculty Nepal, BBS faculty Itahari, Tribhuvan University faculty, education excellence Itahari, teaching staff Godawari College, higher education Itahari, academic staff Sunsari, quality education Nepal, skilled teachers Itahari, college faculty Nepal', '2026-07-14 06:26:36', '2026-07-14 06:26:36');
